export default function UserOrders({ orders }) {
  return (
    <div>
      <h3>📦 Your Orders</h3>

      {orders.length === 0 && <p>No orders yet</p>}

      {orders.map((o, index) => (
        <div key={index} className="order-card">
          <p>Status: <strong>{o.status}</strong></p>

          {o.items.map(i => (
            <p key={i.id}>
              {i.name} × {i.qty}
            </p>
          ))}

          <p>Total: ₹{o.total}</p>
        </div>
      ))}
    </div>
  );
}
